def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def amount(token: str):
        if token and all("0" <= c <= "9" for c in token):
            return int(token)
        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0]
        ok = False
        n = len(parts)

        if verb == "open" and n == 3:
            name, value = parts[1], amount(parts[2])
            if value is not None and value >= 0 and name not in balances:
                balances[name] = value
                history.append(("open", name))
                ok = True
        elif verb == "deposit" and n == 3:
            name, value = parts[1], amount(parts[2])
            if value is not None and value > 0 and name in balances:
                balances[name] += value
                history.append(("deposit", name, value))
                ok = True
        elif verb == "withdraw" and n == 3:
            name, value = parts[1], amount(parts[2])
            if (
                value is not None
                and value > 0
                and name in balances
                and name not in frozen
                and balances[name] >= value
            ):
                balances[name] -= value
                history.append(("withdraw", name, value))
                ok = True
        elif verb == "transfer" and n == 4:
            src, dst, value = parts[1], parts[2], amount(parts[3])
            if (
                value is not None
                and value > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= value
            ):
                balances[src] -= value
                balances[dst] += value
                history.append(("transfer", src, dst, value))
                ok = True
        elif verb == "freeze" and n == 2:
            name = parts[1]
            if name in balances and name not in frozen:
                frozen.add(name)
                history.append(("freeze", name))
                ok = True
        elif verb == "unfreeze" and n == 2:
            name = parts[1]
            if name in balances and name in frozen:
                frozen.remove(name)
                history.append(("unfreeze", name))
                ok = True
        elif verb == "undo" and n == 1 and history:
            kind, *rest = history.pop()
            if kind == "open":
                del balances[rest[0]]
            elif kind == "deposit":
                balances[rest[0]] -= rest[1]
            elif kind == "withdraw":
                balances[rest[0]] += rest[1]
            elif kind == "transfer":
                balances[rest[0]] += rest[2]
                balances[rest[1]] -= rest[2]
            elif kind == "freeze":
                frozen.remove(rest[0])
            else:
                frozen.add(rest[0])
            ok = True

        if not ok:
            rejected.append(i)

    return balances, rejected
